import math

def prime_factorization(N):
    factors = {}
    d = 2
    temp = N
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def omega(N):
    if N == 0:
        return 0
    factors = prime_factorization(N)
    return len(factors)

def calculate_C(n):
    # K = n! / (7 * 17^2)
    # We must ensure n! is divisible by 2023 = 7 * 17^2

    if n < 7:
        return -1 # K is not an integer

    # Calculate v_7(n!) and v_17(n!) using Legendre's formula
    def legendre(n, p):
        count = 0
        i = p
        while i <= n:
            count += n // i
            i *= p
        return count

    v7 = legendre(n, 7)
    v17 = legendre(n, 17)

    if v7 < 1 or v17 < 2:
        return -1 # K is not an integer

    # Now we find omega(K) where K = n! / (7 * 17^2)
    # This is equivalent to counting primes p <= n, and adjusting for p=7 and p=17.

    # A simpler approach given small N: calculate K and use omega(K).
    # However, n! grows very fast. For n=36, 36! is ~3.7 * 10^41. Python handles this.

    try:
        n_factorial = math.factorial(n)
        K = n_factorial // (7 * 17**2)
        return omega(K)
    except OverflowError:
        # Should not happen with Python integers, but defensive coding
        return None

# Test cases based on derived range [34, 36]
test_n = [30, 34, 35, 36, 37, 40]
results = {}

for n in test_n:
    C_n = calculate_C(n)
    results[n] = C_n

print("--- Results for C(n) = omega(n! / 2023) ---")
for n, c in results.items():
    if c != -1:
        print(f"C({n}) = {c}, 2^{c} = {2**c}")
    else:
        print(f"C({n}) = Not an integer (2023 does not divide {n}!)")

# Check the condition 2^C(n) <= 4000
solutions = []
for n in test_n:
    C_n = calculate_C(n)
    if C_n != -1 and 2**C_n <= 4000:
        solutions.append(n)

print("\nSolutions found among test cases:", solutions)
